from pathlib import Path
import sys

root=Path(sys.argv[1])
app=root/'public'/'app.js'
cssp=root/'public'/'styles.css'

a=app.read_text()
if 'ritmoWelcomeMount' not in a:
    a += r'''

// Ritmo V1 — Boas-vindas e instalação inteligente por plataforma.
let ritmoDeferredInstallPrompt=null;
function ritmoIsStandalone(){return window.matchMedia?.('(display-mode: standalone)').matches===true||window.navigator.standalone===true}
function ritmoWelcomePlatform(){const ua=navigator.userAgent||'',ios=/iPad|iPhone|iPod/.test(ua)||(navigator.platform==='MacIntel'&&navigator.maxTouchPoints>1),android=/Android/i.test(ua);return ios?'ios':android?'android':'desktop'}
function ritmoWelcomeIcon(name){const icons={cloud:'<path d="M7.5 18H17a4 4 0 0 0 .7-7.9A6 6 0 0 0 6.3 8.7 4.5 4.5 0 0 0 7.5 18Z"/><path d="m9 13 3-3 3 3"/><path d="M12 10v6"/>',shield:'<path d="M12 3 5 6v5c0 4.6 2.9 8 7 10 4.1-2 7-5.4 7-10V6l-7-3Z"/><path d="m9.5 12 1.7 1.7 3.6-4"/>',phone:'<rect x="7" y="2.8" width="10" height="18.4" rx="2.4"/><path d="M10 5h4"/><path d="M11 18.5h2"/>',share:'<path d="M12 3v12"/><path d="m8 7 4-4 4 4"/><rect x="5" y="10" width="14" height="11" rx="2"/>',plus:'<path d="M12 5v14M5 12h14"/>',desktop:'<rect x="3" y="4" width="18" height="12" rx="2"/><path d="M8 21h8M12 16v5"/>',check:'<path d="m5 12 4 4L19 6"/>'};return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.check}</svg>`}
function ritmoWelcomeSteps(platform){if(platform==='ios')return `<div class="welcome-install-card"><div class="welcome-install-head"><span>${ritmoWelcomeIcon('phone')}</span><div><strong>Instale no iPhone ou iPad</strong><small>Leva poucos segundos pelo Safari.</small></div></div><div class="welcome-steps"><div><b>1</b><span>Abra este link no <strong>Safari</strong>.</span></div><div><b>2</b><span>Toque em <i class="welcome-inline-icon">${ritmoWelcomeIcon('share')}</i> <strong>Compartilhar</strong>.</span></div><div><b>3</b><span>Escolha <strong>Adicionar à Tela de Início</strong>.</span></div><div><b>4</b><span>Confirme em <strong>Adicionar</strong>.</span></div></div></div>`;
if(platform==='android')return `<div class="welcome-install-card"><div class="welcome-install-head"><span>${ritmoWelcomeIcon('phone')}</span><div><strong>Instale no Android</strong><small>Tenha o Ritmo como um app no seu celular.</small></div></div><div class="welcome-steps"><div><b>1</b><span>Toque em <strong>Instalar Ritmo</strong> abaixo.</span></div><div><b>2</b><span>Se o botão não aparecer, abra o menu do navegador.</span></div><div><b>3</b><span>Escolha <strong>Instalar aplicativo</strong> ou <strong>Adicionar à tela inicial</strong>.</span></div></div></div>`;
return `<div class="welcome-install-card welcome-desktop-card"><div class="welcome-install-head"><span>${ritmoWelcomeIcon('desktop')}</span><div><strong>Ritmo no seu computador</strong><small>Instale para abrir em uma janela própria, como um aplicativo.</small></div></div></div>`}
function ritmoWelcomeMarkup(){const platform=ritmoWelcomePlatform(),mobile=platform!=='desktop';return `<div class="ritmo-welcome" id="ritmoWelcome" role="dialog" aria-modal="true" aria-labelledby="ritmoWelcomeTitle"><div class="welcome-shell"><div class="welcome-brand"><img src="/ritmo-logo.png" alt="Ritmo"><span class="welcome-version">Versão 1.0</span></div><div class="welcome-hero"><div class="welcome-orbit one"></div><div class="welcome-orbit two"></div><div class="welcome-icon-wrap"><img src="/ritmo-icon-192.png" alt=""></div><span class="welcome-eyebrow">SEJA BEM-VINDO</span><h1 id="ritmoWelcomeTitle">Seu dinheiro no seu ritmo.</h1><p>Organize sua vida financeira com clareza, segurança e uma experiência feita para acompanhar você em qualquer aparelho.</p><div class="welcome-benefits"><span>${ritmoWelcomeIcon('cloud')} Sincronizado na nuvem</span><span>${ritmoWelcomeIcon('shield')} Conta protegida</span><span>${ritmoWelcomeIcon('check')} Simples de usar</span></div></div>${ritmoWelcomeSteps(platform)}<div class="welcome-actions"><button type="button" class="welcome-install-primary" id="ritmoWelcomeInstall">${ritmoWelcomeIcon(mobile?'phone':'desktop')} ${platform==='ios'?'Ver como instalar':'Instalar Ritmo'}</button><button type="button" class="welcome-continue" id="ritmoWelcomeContinue">Continuar para o Ritmo</button></div><div class="welcome-install-hint" id="ritmoWelcomeHint" hidden></div><footer class="welcome-footer"><span>Ritmo • gestão financeira pessoal</span><strong>Desenvolvedor: Flávio Rocha</strong></footer></div></div>`}
function ritmoWelcomeClose(){try{sessionStorage.setItem('ritmo:welcome-session','1')}catch{}document.getElementById('ritmoWelcome')?.remove()}
function ritmoWelcomeSetInstallReady(){const btn=document.getElementById('ritmoWelcomeInstall');if(!btn)return;const p=ritmoWelcomePlatform();if(ritmoDeferredInstallPrompt&&p!=='ios'){btn.classList.add('ready');btn.innerHTML=`${ritmoWelcomeIcon(p==='desktop'?'desktop':'phone')} Instalar Ritmo`}}
async function ritmoWelcomeInstall(){const p=ritmoWelcomePlatform(),hint=document.getElementById('ritmoWelcomeHint');if(p==='ios'){if(hint){hint.hidden=false;hint.textContent='No iPhone, use Compartilhar → Adicionar à Tela de Início.'}return}if(ritmoDeferredInstallPrompt){try{ritmoDeferredInstallPrompt.prompt();const choice=await ritmoDeferredInstallPrompt.userChoice;ritmoDeferredInstallPrompt=null;if(choice?.outcome==='accepted'){if(hint){hint.hidden=false;hint.textContent='Instalação iniciada. O Ritmo ficará disponível como aplicativo.'}setTimeout(ritmoWelcomeClose,700)}else if(hint){hint.hidden=false;hint.textContent='Tudo bem. Você pode instalar quando quiser.'}}catch{if(hint){hint.hidden=false;hint.textContent='Use a opção Instalar aplicativo no menu do navegador.'}}return}if(hint){hint.hidden=false;hint.textContent=p==='desktop'?'Se o navegador oferecer instalação, use o ícone de instalar na barra de endereço.':'Abra o menu do navegador e escolha Instalar aplicativo.'}}
function ritmoWelcomeMount(){if(ritmoIsStandalone())return;try{if(sessionStorage.getItem('ritmo:welcome-session')==='1')return}catch{}if(document.getElementById('ritmoWelcome'))return;document.body.insertAdjacentHTML('beforeend',ritmoWelcomeMarkup());document.getElementById('ritmoWelcomeContinue')?.addEventListener('click',ritmoWelcomeClose);document.getElementById('ritmoWelcomeInstall')?.addEventListener('click',ritmoWelcomeInstall);ritmoWelcomeSetInstallReady()}
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();ritmoDeferredInstallPrompt=e;ritmoWelcomeSetInstallReady()});
window.addEventListener('appinstalled',()=>{ritmoDeferredInstallPrompt=null;const h=document.getElementById('ritmoWelcomeHint');if(h){h.hidden=false;h.textContent='Ritmo instalado com sucesso.'}setTimeout(ritmoWelcomeClose,650)});
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',()=>setTimeout(ritmoWelcomeMount,20),{once:true});else setTimeout(ritmoWelcomeMount,20);
'''
app.write_text(a)

css=cssp.read_text()
if '.ritmo-welcome{' not in css:
    css += r'''

/* Ritmo V1 — boas-vindas e instalação */
.ritmo-welcome{position:fixed;inset:0;z-index:99999;overflow:auto;background:linear-gradient(150deg,#F7F5EF 0%,#eef4f1 48%,#f5eee6 100%);color:#2E2E2E;padding:max(18px,env(safe-area-inset-top)) 16px max(18px,env(safe-area-inset-bottom));font-family:inherit}.welcome-shell{width:min(880px,100%);min-height:calc(100dvh - 36px);margin:0 auto;display:flex;flex-direction:column}.welcome-brand{display:flex;align-items:center;justify-content:space-between;gap:16px;padding:5px 2px 18px}.welcome-brand img{width:min(175px,46vw);height:auto;object-fit:contain}.welcome-version{font-size:10px;font-weight:700;color:#0F4C5C;background:rgba(15,76,92,.08);padding:6px 9px;border-radius:999px}.welcome-hero{position:relative;overflow:hidden;text-align:center;background:rgba(255,255,255,.72);border:1px solid rgba(15,76,92,.09);border-radius:30px;padding:30px 20px 25px;box-shadow:0 18px 55px rgba(15,76,92,.08);backdrop-filter:blur(16px)}.welcome-icon-wrap{position:relative;z-index:2;width:86px;height:86px;border-radius:25px;margin:0 auto 16px;padding:8px;background:#fff;box-shadow:0 12px 30px rgba(15,76,92,.14)}.welcome-icon-wrap img{width:100%;height:100%;border-radius:19px;object-fit:cover}.welcome-eyebrow{position:relative;z-index:2;display:block;color:#7CA982;font-size:10px;font-weight:800;letter-spacing:.16em;margin-bottom:8px}.welcome-hero h1{position:relative;z-index:2;margin:0;color:#0F4C5C;font-size:clamp(28px,6vw,46px);line-height:1.03;letter-spacing:-.04em}.welcome-hero>p{position:relative;z-index:2;max-width:580px;margin:14px auto 0;color:#67706e;font-size:13px;line-height:1.65}.welcome-benefits{position:relative;z-index:2;display:flex;justify-content:center;flex-wrap:wrap;gap:7px;margin-top:18px}.welcome-benefits span{display:inline-flex;align-items:center;gap:5px;background:#fff;border:1px solid rgba(15,76,92,.08);border-radius:999px;padding:7px 10px;color:#55615e;font-size:9.5px;font-weight:650}.welcome-benefits svg{width:14px;height:14px;color:#7CA982}.welcome-orbit{position:absolute;border-radius:50%;filter:blur(.2px);pointer-events:none}.welcome-orbit.one{width:220px;height:220px;right:-100px;top:-110px;background:rgba(212,163,115,.16)}.welcome-orbit.two{width:170px;height:170px;left:-90px;bottom:-90px;background:rgba(124,169,130,.15)}.welcome-install-card{margin-top:14px;background:rgba(255,255,255,.86);border:1px solid rgba(15,76,92,.09);border-radius:22px;padding:15px;box-shadow:0 8px 26px rgba(15,76,92,.045)}.welcome-install-head{display:flex;align-items:center;gap:11px;text-align:left}.welcome-install-head>span{width:40px;height:40px;display:grid;place-items:center;border-radius:13px;background:rgba(15,76,92,.08);color:#0F4C5C;flex:0 0 auto}.welcome-install-head svg{width:21px;height:21px}.welcome-install-head div{display:flex;flex-direction:column}.welcome-install-head strong{font-size:12px;color:#2E2E2E}.welcome-install-head small{font-size:9.5px;color:#7a827f;margin-top:2px}.welcome-steps{display:grid;gap:0;margin-top:13px;border-top:1px solid rgba(15,76,92,.07)}.welcome-steps>div{display:flex;align-items:center;gap:10px;min-height:42px;border-bottom:1px solid rgba(15,76,92,.06);font-size:10.5px;color:#58615f}.welcome-steps>div:last-child{border-bottom:0}.welcome-steps b{width:23px;height:23px;display:grid;place-items:center;border-radius:50%;background:#F7F5EF;color:#0F4C5C;font-size:9px}.welcome-inline-icon{display:inline-grid;vertical-align:middle;width:16px;height:16px;color:#0F4C5C}.welcome-inline-icon svg{width:16px;height:16px}.welcome-desktop-card{padding:17px}.welcome-actions{display:grid;grid-template-columns:1fr 1fr;gap:9px;margin-top:14px}.welcome-install-primary,.welcome-continue{min-height:48px;border-radius:15px;border:0;font:inherit;font-size:11px;font-weight:800;cursor:pointer;display:flex;align-items:center;justify-content:center;gap:7px}.welcome-install-primary{background:#0F4C5C;color:white;box-shadow:0 8px 20px rgba(15,76,92,.18)}.welcome-install-primary.ready{box-shadow:0 9px 24px rgba(15,76,92,.26)}.welcome-install-primary svg,.welcome-continue svg{width:17px;height:17px}.welcome-continue{background:rgba(255,255,255,.85);color:#0F4C5C;border:1px solid rgba(15,76,92,.12)}.welcome-install-hint{margin-top:9px;border-radius:12px;background:rgba(212,163,115,.14);color:#77542c;padding:9px 11px;text-align:center;font-size:9.5px;line-height:1.4}.welcome-footer{margin-top:auto;padding:18px 5px 3px;display:flex;align-items:center;justify-content:space-between;gap:12px;color:#747d7a;font-size:9px}.welcome-footer strong{font-weight:750;color:#0F4C5C}@media(max-width:640px){.ritmo-welcome{padding-left:12px;padding-right:12px}.welcome-shell{min-height:calc(100dvh - 30px)}.welcome-brand{padding-bottom:13px}.welcome-hero{border-radius:25px;padding:24px 15px 21px}.welcome-icon-wrap{width:78px;height:78px;border-radius:22px}.welcome-benefits{gap:5px}.welcome-benefits span{font-size:8.7px;padding:6px 8px}.welcome-install-card{border-radius:19px}.welcome-actions{grid-template-columns:1fr}.welcome-install-primary,.welcome-continue{min-height:47px}.welcome-footer{flex-direction:column;text-align:center;gap:4px;padding-top:15px}}@media(min-width:760px){.welcome-shell{justify-content:center;padding:22px 0}.welcome-brand{padding-top:0}.welcome-hero{padding:34px 30px 28px}.welcome-install-card{max-width:700px;width:100%;margin-left:auto;margin-right:auto}.welcome-actions{max-width:700px;width:100%;margin-left:auto;margin-right:auto;margin-top:12px}.welcome-footer{max-width:700px;width:100%;margin-left:auto;margin-right:auto}}
'''
cssp.write_text(css)
print('Ritmo V1: tela de boas-vindas e instalação adaptativa adicionada. Desenvolvedor: Flávio Rocha.')
